    b += t(82, 425, '低 ' + fmt(lo, 1)) + t(340, 425, fmt(hi, 1) + ' 高', 'text-anchor="end"'); $('surface').innerHTML = svg(530, 450, '孔密与穿深的受约束性能热图，相位' + phase + '度', b);
    const choose = i => { const r = rows[i]; $('point-detail').textContent = r.density + ' 孔/m · ' + r.penetration + ' cm · ' + r.phase + '°：预测响应 ' + fmt(r.prediction) + '，成本 ' + fmt(r.cost) + ' 点，净目标 ' + fmt(r.objective) + '；' + (r.feasible ? '满足全部约束。' : r.reasons.join('；') + '。'); renderGeometry(r); };
    $('surface').querySelectorAll('[data-cell]').forEach(el => { el.onclick = () => choose(Number(el.dataset.cell)); el.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); choose(Number(el.dataset.cell)); } }; });
