      const warns = []; if (pred.outOfDomain.length) warns.push('当前储层条件超出训练范围：' + pred.outOfDomain.map(k => ({ permeability: '渗透率', damage: '损伤带', anisotropy: '各向异性' }[k])).join('、') + '。候选列为外推，优先复核。'); if (!pred.baseline.feasible) warns.push('固定方案：' + pred.baseline.reasons.join('；') + '，不与可行方案直接比较收益。'); $('warnings').hidden = !warns.length; $('warnings').textContent = warns.join(' ');
      if (pred.selected) $('view-phase').value = pred.selected.phase; renderSurface(); renderTradeoff(); renderParity(); renderComparison(); setStatus('done', '计算完成 · ' + active.runId + ' · ' + pred.candidateCount + ' 个候选真实搜索');
